import{_ as a,c as t,o as p,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"12、【否】 坤下乾上","description":"溫公易說 - 12、【否】 坤下乾上","frontmatter":{"title":"12、【否】 坤下乾上","description":"溫公易說 - 12、【否】 坤下乾上"},"headers":[],"relativePath":"classics/wengong/013.md","filePath":"classics/wengong/013.md"}'),n={name:"classics/wengong/013.md"};function r(o,e,_,c,i,l){return p(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="_12、【否】-坤下乾上" tabindex="-1">12、【否】 坤下乾上 <a class="header-anchor" href="#_12、【否】-坤下乾上" aria-label="Permalink to “12、【否】 坤下乾上”">​</a></h1><p>否之匪人，不利君子貞，大往小來。</p><p>彖曰：否之匪人，不利君子貞，大往小來，則是天地不交而萬物不通也，上下不交而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子。小人道長，君子道消也。否之匪人何也？凡君子小人更為否泰也。故君子泰則小人否，君子否則天下亂，小人否則天下治。今大往小來，則君子之道否也，故曰否之匪人。否之所施，非其人也。否者，壅塞使之不進之謂也。</p><p>象曰：天地不交，否。君子以儉德闢難，不可榮以祿。</p><p>初六：拔茅茹，以其彚，貞吉，亨 象曰：拔茅，貞吉，志在君也。</p><p>六二：包承，小人吉，大人否，亨 象曰：大人否，亨，不亂群也。否而得位以柔，應君包承者也。故小人居之則為吉，大人居之則為否。然大人者，體順履正，和而不同，否不能久，久而必通，故曰亨也。</p><p>六三：包羞 象曰：包羞，位不當也。君子之不得其時也。失位而居於下，則為小人之所侮；居於上，則為君子之所恥。故六三不當其位，而進退包羞也。</p><p>九四：有命，無咎，疇離祉 象曰：有命，無咎，志行也。四者，陰退而陽進之時也。命者，上之所以施於下也。四以陽居上，變否為泰，命之所施必施於賢者。賢人進，則泰之端見矣，故有命無咎。疇者，群陽之謂也。陽德將亨，故曰疇離祉。</p><p>九五：休否，大人吉，其亡其亡，繫於苞桑 象曰：大人之吉，位正當也。</p><p>上九：傾否，先否後喜 象曰：否終則傾，何可長也。</p>',10)])])}const m=a(n,[["render",r]]);export{f as __pageData,m as default};
